//! Provider model operations and row presentation.

use gpui_kit::{AppContext as _, Context, Entity, IntoElement, ParentElement as _, Styled as _, Window, base::{h_flex, v_flex}, component::{button::{Button, ButtonVariants as _}, input::{Input, InputState}, switch::Switch}, prelude::FluentBuilder as _};
use thinkrail_core::{ProbeTarget, ProviderModel, Protocol, Secret, ThinkingLevel};
use thinkrail_ui::{ThinkrailTheme, components::{Segment, label}, metrics::{space, text}};
use crate::{state::run, strings::settings_providers as s};
use super::{draft::{effort_label, parse_headers, EFFORTS, PROTOCOLS, protocol_index, protocol_label}, ProvidersPage};

pub(crate) struct ModelFields {
    pub(crate) id: String, pub(crate) name: Entity<InputState>, pub(crate) context_window: Entity<InputState>, pub(crate) max_tokens: Entity<InputState>,
    pub(crate) protocols: Vec<Protocol>, pub(crate) efforts: Vec<ThinkingLevel>, pub(crate) vision: bool, pub(crate) reasoning: bool, pub(crate) tools: bool, pub(crate) enabled: bool,
    pub(crate) expanded: bool, pub(crate) checking: bool, pub(crate) check_result: Option<String>,
}
impl ModelFields {
    pub(crate) fn from_model(model: &ProviderModel, window: &mut Window, cx: &mut Context<ProvidersPage>) -> Self {
        let name = cx.new(|cx| InputState::new(window, cx)); let context_window = cx.new(|cx| InputState::new(window, cx)); let max_tokens = cx.new(|cx| InputState::new(window, cx));
        super::set_input(&name, model.name.clone(), window, cx); super::set_input(&context_window, model.context_window.map(|v| v.to_string()).unwrap_or_default(), window, cx); super::set_input(&max_tokens, model.max_tokens.map(|v| v.to_string()).unwrap_or_default(), window, cx);
        Self { id: model.model_id.clone(), name, context_window, max_tokens, protocols: model.protocols.clone(), efforts: model.efforts.clone(), vision: model.vision, reasoning: model.reasoning, tools: model.tools, enabled: model.enabled, expanded: false, checking: false, check_result: None }
    }
    pub(crate) fn to_model(&self, cx: &Context<ProvidersPage>) -> Result<ProviderModel, &'static str> {
        let name = self.name.read(cx).value().trim().to_owned(); if self.id.trim().is_empty() || name.is_empty() || self.protocols.is_empty() { return Err(s::MODEL_ID_REQUIRED); }
        let number = |field: &Entity<InputState>| { let raw = field.read(cx).value().trim().to_owned(); if raw.is_empty() { Ok(None) } else { raw.parse::<u32>().map(Some).map_err(|_| s::MODEL_ID_REQUIRED) } };
        Ok(ProviderModel { model_id: self.id.clone(), name, protocols: self.protocols.clone(), context_window: number(&self.context_window)?, max_tokens: number(&self.max_tokens)?, vision: self.vision, reasoning: self.reasoning, tools: self.tools, efforts: if self.reasoning { self.efforts.clone() } else { Vec::new() }, enabled: self.enabled })
    }
}

impl ProvidersPage {
    pub(super) fn add_model(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(editor) = &mut self.editing else { return; };
        let id = editor.model_id.read(cx).value().trim().to_owned();
        if id.is_empty() { self.error = Some(s::MODEL_ID_REQUIRED.to_owned()); return; }
        if editor.models.iter().any(|model| model.id == id) { return; }
        let protocol = editor.default_protocol.read(cx).selected_value().copied().unwrap_or(Protocol::OpenaiChat);
        let model = ProviderModel { model_id: id, name: String::new(), protocols: vec![protocol], context_window: None, max_tokens: None, vision: false, reasoning: false, tools: true, efforts: Vec::new(), enabled: false };
        editor.models.push(ModelFields::from_model(&model, window, cx));
        editor.model_id.update(cx, |input, cx| input.set_value(String::new(), window, cx));
        cx.notify();
    }
    pub(super) fn toggle_model(&mut self, index: usize, enabled: bool, cx: &mut Context<Self>) { if let Some(model) = self.editing.as_mut().and_then(|editor| editor.models.get_mut(index)) { model.enabled = enabled; cx.notify(); } }
    pub(super) fn discover(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(editor) = &self.editing else { return; }; if editor.probing { return; } let protocol = editor.default_protocol.read(cx).selected_value().copied().unwrap_or(Protocol::OpenaiChat); let endpoint = match self.endpoint(protocol, cx) { Ok(endpoint) => endpoint, Err(error) => { self.error = Some(error.to_owned()); return; } }; let headers = match parse_headers(&editor.headers, cx) { Ok(headers) => headers, Err(error) => { self.error = Some(error.to_owned()); return; } }; let pending_key = self.input(&editor.key_value, cx).trim().to_owned(); let id = editor.id.clone(); let providers = self.state.read(cx).services.providers.clone(); let probe = self.state.read(cx).services.probe.clone(); let window_handle = window.window_handle(); if let Some(editor) = &mut self.editing { editor.probing = true; }
        run(cx, move || { let key = if pending_key.is_empty() { id.as_ref().map(|id| providers.provider(id)).transpose()?.and_then(|provider| provider.keys.into_iter().find(|key| key.enabled)).map(|key| providers.reveal_key(&key.id)).transpose()? } else { Some(Secret::new(pending_key)) }; probe.list_models(&ProbeTarget { endpoint, headers, key }) }, move |this, result, cx| match result {
            Ok(models) => { let protocol = this.editing.as_ref().and_then(|editor| editor.default_protocol.read(cx).selected_value().copied()).unwrap_or(protocol); let view = cx.entity(); let _ = window_handle.update(cx, move |_, window, cx| view.update(cx, |page, cx| { if let Some(editor) = &mut page.editing { editor.probing = false; editor.discovered = models.clone(); for discovered in models { if editor.models.iter().any(|model| model.id == discovered.id) { continue; } let model = ProviderModel { model_id: discovered.id.clone(), name: discovered.name.unwrap_or(discovered.id), protocols: vec![protocol], context_window: discovered.context_window, max_tokens: None, vision: false, reasoning: false, tools: true, efforts: Vec::new(), enabled: false }; editor.models.push(ModelFields::from_model(&model, window, cx)); } cx.notify(); } })); }
            Err(error) => { if let Some(editor) = &mut this.editing { editor.probing = false; } this.error = Some(error.to_string()); this.state.update(cx, |state, cx| state.report(&error, cx)); cx.notify(); }
        });
    }
    pub(super) fn check_model(&mut self, index: usize, cx: &mut Context<Self>) { let Some(editor) = &self.editing else { return; }; let Some(model) = editor.models.get(index) else { return; }; let default_protocol = editor.default_protocol.read(cx).selected_value().copied().unwrap_or(Protocol::OpenaiChat); let protocol = model.protocols.first().copied().unwrap_or(default_protocol); let endpoint = match self.endpoint(protocol, cx) { Ok(endpoint) => endpoint, Err(error) => { self.error = Some(error.to_owned()); return; } }; let headers = match parse_headers(&editor.headers, cx) { Ok(headers) => headers, Err(error) => { self.error = Some(error.to_owned()); return; } }; let id = editor.id.clone(); let model_id = model.id.clone(); let providers = self.state.read(cx).services.providers.clone(); let probe = self.state.read(cx).services.probe.clone(); if let Some(model) = self.editing.as_mut().and_then(|editor| editor.models.get_mut(index)) { model.checking = true; } run(cx, move || { let key = id.as_ref().map(|id| providers.provider(id)).transpose()?.and_then(|provider| provider.keys.into_iter().find(|key| key.enabled)).map(|key| providers.reveal_key(&key.id)).transpose()?; probe.check(&ProbeTarget { endpoint, headers, key }, &model_id) }, move |this, result, cx| { if let Some(model) = this.editing.as_mut().and_then(|editor| editor.models.get_mut(index)) { model.checking = false; model.check_result = Some(match result { Ok(ms) => s::model_check_ok(ms), Err(error) => s::model_check_error(&error.to_string()) }); } cx.notify(); }); }
    pub(super) fn render_model(&self, index: usize, model: &ModelFields, cx: &mut Context<Self>) -> impl IntoElement + use<> { let r = ThinkrailTheme::global(cx).roles; let id = model.id.clone(); let expanded = model.expanded; let protocols = model.protocols.clone(); let efforts = model.efforts.clone(); let check_result = model.check_result.clone(); v_flex().gap(space::S4).py(space::S6).border_b_1().border_color(r.border_muted).child(h_flex().gap(space::S4).child(Button::new(format!("provider-model-expand-{index}")).ghost().label(if expanded { "⌄" } else { "›" }).on_click(cx.listener(move |this, _, _, cx| { if let Some(model) = this.editing.as_mut().and_then(|editor| editor.models.get_mut(index)) { model.expanded = !model.expanded; cx.notify(); } }))).child(label(text::UI, format!("{} · {id}", model.name.read(cx).value())).flex_1()).child(Switch::new(format!("provider-model-enabled-{index}")).checked(model.enabled).color(r.feedback_success).on_click(cx.listener(move |this, value: &bool, _, cx| this.toggle_model(index, *value, cx)))).child(Button::new(format!("provider-model-check-{index}")).ghost().label(if model.checking { s::PROBING } else { s::CHECK }).on_click(cx.listener(move |this, _, _, cx| this.check_model(index, cx))))) .when(expanded, |view| view.child(v_flex().gap(space::S4).pl(space::S24).child(v_flex().gap(space::S2).child(label(text::TITLE_COMPACT, s::MODEL_NAME).text_color(r.text_muted)).child(Input::new(&model.name))).child(label(text::TITLE_COMPACT, s::PROTOCOLS).text_color(r.text_muted)).child(Segment::new(format!("provider-model-protocol-{index}"), PROTOCOLS.map(protocol_label), protocol_index(protocols.first().copied().unwrap_or(Protocol::OpenaiChat))).on_select(cx.listener(move |this, selected: &usize, _, cx| { if let Some(model) = this.editing.as_mut().and_then(|editor| editor.models.get_mut(index)) { let protocol = PROTOCOLS[*selected]; model.protocols.retain(|item| *item != protocol); model.protocols.insert(0, protocol); cx.notify(); } }))).child(h_flex().gap(space::S4).children([Switch::new(format!("provider-model-vision-{index}")).checked(model.vision).color(r.feedback_success).label(s::VISION), Switch::new(format!("provider-model-reasoning-{index}")).checked(model.reasoning).color(r.feedback_success).label(s::REASONING), Switch::new(format!("provider-model-tools-{index}")).checked(model.tools).color(r.feedback_success).label(s::TOOLS)])).child(label(text::TITLE_COMPACT, s::EFFORTS).text_color(r.text_muted)).child(h_flex().gap(space::S2).children(EFFORTS.map(|effort| { let selected = efforts.contains(&effort); Button::new(format!("provider-effort-{index}-{}", effort_label(effort))).ghost().label(effort_label(effort)).when(selected, |button| button.primary()).on_click(cx.listener(move |this, _, _, cx| { if let Some(model) = this.editing.as_mut().and_then(|editor| editor.models.get_mut(index)) { if model.efforts.contains(&effort) { model.efforts.retain(|item| *item != effort); } else { model.efforts.push(effort); } cx.notify(); } })) }))).when_some(check_result, |view, result| view.child(label(text::METADATA, result).text_color(r.text_subtle))).child(Button::new(format!("provider-model-remove-{index}")).ghost().label(s::DELETE).on_click(cx.listener(move |this, _, _, cx| { if let Some(editor) = &mut this.editing && index < editor.models.len() { editor.models.remove(index); cx.notify(); } }))))).into_any_element() }
}
